/* UI renders the complete compact snapshot projection; all calculations use engine.js. */
(function () {
  'use strict';
  const D = window.RADAR_DATA, E = globalThis.RadarEngine, main = document.querySelector('main');
  if (!D || !E) { main.textContent = 'Data missing. Run node main.ts --preview, or open output/dashboard/index.html.'; return; }
  const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' })[c]);
  const money = n => '$' + (n >= 1e9 ? (n / 1e9).toFixed(2) + 'B' : n >= 1e6 ? (n / 1e6).toFixed(2) + 'M' : n >= 1e3 ? (n / 1e3).toFixed(1) + 'K' : n.toFixed(2));
  const dollars = n => '$' + Math.round(n).toLocaleString('en-US');
  const ratio = n => n.toFixed(3) + '×';
  const pct = n => n === null ? 'Not reported' : (n > 0 ? '+' : '') + n.toFixed(2) + '%';
  const peers = D.peers.map(a => ({ slug:a[0], name:a[1], category:D.categories[a[2]], tvl_usd:a[3], mcap_usd:a[4], token:a[5] }));
  const rows = D.rows.map(a => {
    const p = { slug:a[0], name:a[1], category:D.categories[a[2]], chains:a[3].map(i => D.chains[i]), tvl_usd:a[4], change_7d:a[5], listed_at:a[6], watchlist:!!a[7] };
    return { ...p, model:E.valuation(p, D.date, peers), plan:E.farmPlan(p, D.date) };
  }).sort((a, b) => b.model.implied_value_usd - a.model.implied_value_usd || (a.slug < b.slug ? -1 : 1));
  rows.forEach((p, i) => { p.rank = i + 1; p.implied_value_usd = p.model.implied_value_usd; });
  const state = { search:'', category:'', chain:'', tvl:'', value:'', cohort:'', sort:'implied_value_usd', asc:false, page:0 }, pageSize = 8;
  let filtered = [];
  document.querySelector('#footer-date').textContent = 'DEFILLAMA / ' + D.date + ' UTC · ZERO NETWORK REQUESTS';
  function stat(label, value, note, color = '') { return `<div class="stat"><div class="stat-label">${label}</div><div class="stat-value ${color}">${value}</div><div class="stat-note">${note}</div></div>`; }
  function options(values, selected) { return values.map(x => `<option value="${esc(x)}" ${x === selected ? 'selected' : ''}>${esc(x || 'Unreported')}</option>`).join(''); }
  function field(id, label, content) { return `<label>${label}<select id="${id}">${content}</select></label>`; }
  function sortHead(key, text, num = false) { return `<th scope="col" ${num ? 'class="num"' : ''} aria-sort="${state.sort === key ? state.asc ? 'ascending' : 'descending' : 'none'}"><button data-sort="${key}">${text} ${state.sort === key ? state.asc ? '↑' : '↓' : '↕'}</button></th>`; }
  function board() {
    main.innerHTML = `<section class="hero"><div><div class="kicker">THE PRE-LAUNCH RESEARCH DESK</div><h1>Find the signal before the token.</h1><p>Protocols with no token recorded, ranked by a defensible launch value.<br>Snapshot evidence. Conditional farm plans. Every assumption in the open.</p></div><div class="stamp">SEALED SNAPSHOT<br><strong>${D.date} / UTC</strong><br>MODEL UNISSUED—01</div></section>
    <section class="stats" aria-label="Radar summary">${stat('On the radar', rows.length, (rows.length - D.watch) + ' extended candidates', 'mint')}${stat('Watchlist covered', D.watch + ' / ' + D.watch, 'Every required protocol included')}${stat('Token comparables', peers.length, D.tokens + ' token-recorded protocols set aside')}${stat('Highest implied value', money(rows[0].implied_value_usd), esc(rows[0].name) + ' · circulating-cap proxy', 'cyan')}</section>
    <div class="layout"><aside class="filters" aria-label="Filter protocols"><div class="filter-head"><h2>Refine the radar</h2><button id="reset" class="text-button">Reset all</button></div>
    <label>Find a protocol<input id="search" type="search" placeholder="Name or slug…" value="${esc(state.search)}"></label>
    ${field('category','Category','<option value="">All categories</option>' + options([...new Set(rows.map(p => p.category))].sort(), state.category))}
    ${field('chain','Chain','<option value="">All chains</option>' + options([...new Set(rows.flatMap(p => p.chains))].sort(), state.chain))}
    ${field('tvl','TVL band','<option value="">Any TVL</option><option value="small">Below $50M</option><option value="mid">$50M–$500M</option><option value="large">$500M and above</option>')}
    ${field('value','Implied value band','<option value="">Any implied value</option><option value="small">Below $25M</option><option value="mid">$25M–$250M</option><option value="large">$250M and above</option>')}
    ${field('cohort','Coverage group','<option value="">Watchlist + extended</option><option value="watch">Required watchlist</option><option value="early">Extended candidates</option>')}
    <p class="filter-note"><strong>No token recorded ≠ no token.</strong><br>Issuer, access and campaign status need independent verification. Extended candidates may be parent products.</p></aside>
    <section aria-label="Ranked protocols"><div class="board-head"><h2>Launch radar <span class="pill" id="count"></span></h2><span class="legend">Value = hypothetical circulating market cap</span></div><div id="board-results"></div><div class="model-strip"><span>TVL × peer multiple × growth × tracking maturity × 0.70 transfer discount</span><a href="#method">Inspect the model</a></div></section></div>`;
    ['tvl','value','cohort'].forEach(id => document.getElementById(id).value = state[id]);
    ['search','category','chain','tvl','value','cohort'].forEach(id => document.getElementById(id).addEventListener(id === 'search' ? 'input' : 'change', e => { state[id] = e.target.value; state.page = 0; renderResults(); }));
    document.getElementById('reset').onclick = () => { ['search','category','chain','tvl','value','cohort'].forEach(id => state[id] = ''); state.page = 0; state.sort = 'implied_value_usd'; state.asc = false; board(); };
    renderResults();
  }
  function inBand(n, band, a, b) { return !band || (band === 'small' ? n < a : band === 'mid' ? n >= a && n < b : n >= b); }
  function renderResults() {
    filtered = rows.filter(p => (!state.search || (p.name + ' ' + p.slug).toLowerCase().includes(state.search.toLowerCase())) && (!state.category || p.category === state.category) && (!state.chain || p.chains.includes(state.chain)) && inBand(p.tvl_usd, state.tvl, 5e7, 5e8) && inBand(p.implied_value_usd, state.value, 25e6, 250e6) && (!state.cohort || (state.cohort === 'watch' ? p.watchlist : !p.watchlist)));
    filtered.sort((a,b) => {
      const x = a[state.sort], y = b[state.sort];
      const d = typeof x === 'string' ? x.localeCompare(y, 'en') : (x ?? -Infinity) - (y ?? -Infinity);
      return (state.asc ? d : -d) || a.rank - b.rank;
    });
    document.querySelector('#count').textContent = `${filtered.length} / ${rows.length}`;
    const start = state.page * pageSize, shown = filtered.slice(start, start + pageSize);
    document.querySelector('#board-results').innerHTML = `<div class="table-wrap"><table><caption class="skip">Protocols sorted by ${esc(state.sort)}, ${state.asc ? 'ascending' : 'descending'}</caption><thead><tr>${sortHead('rank','#')}${sortHead('name','Protocol')}${sortHead('category','Category')}${sortHead('tvl_usd','TVL',true)}${sortHead('change_7d','7D TVL',true)}${sortHead('implied_value_usd','Implied value',true)}<th scope="col">Farm route</th></tr></thead><tbody>${shown.map(p => `<tr><td class="rank">${String(p.rank).padStart(2,'0')}</td><td><a class="name-link" href="#protocol/${encodeURIComponent(p.slug)}">${esc(p.name)}</a><div class="row-meta" title="${esc(p.chains.join(', '))}">${esc(p.chains.slice(0,2).join(' · '))}${p.chains.length > 2 ? ' +' + (p.chains.length - 2) : ''} · ${p.watchlist ? 'watchlist' : 'extended'}</div></td><td class="category">${esc(p.category || 'Unreported')}</td><td class="num">${money(p.tvl_usd)}</td><td class="num ${p.change_7d === null ? '' : p.change_7d >= 0 ? 'positive' : 'negative'}">${pct(p.change_7d)}</td><td class="num value">${money(p.implied_value_usd)}<div class="bar"><i style="width:${Math.max(2,100 * p.implied_value_usd / rows[0].implied_value_usd)}%"></i></div></td><td><span class="pill ${p.plan.capital_usd ? 'cyan' : 'neutral'}">${p.plan.capital_usd ? '$' + p.plan.capital_usd + ' / ' + p.plan.duration_days + 'd' : 'Research first'}</span><div class="row-meta">${p.model.peer_count} category peers</div></td></tr>`).join('') || '<tr><td colspan="7" class="empty">No protocols match. Reset the filters to explore the full radar.</td></tr>'}</tbody></table></div>
    <div class="pager"><span id="results-status" role="status" aria-live="polite">${filtered.length ? start + 1 : 0}–${Math.min(start + pageSize, filtered.length)} of ${filtered.length} protocols · click a name for the dossier</span><div><button id="prev" ${state.page === 0 ? 'disabled' : ''}>Previous</button><button id="next" ${start + pageSize >= filtered.length ? 'disabled' : ''}>Next</button></div></div>`;
    document.querySelectorAll('[data-sort]').forEach(el => el.onclick = () => { const key = el.dataset.sort; state.asc = key === state.sort ? !state.asc : ['name','category','rank'].includes(key); state.sort = key; state.page = 0; renderResults(); });
    document.querySelector('#prev').onclick = () => { state.page--; renderResults(); };
    document.querySelector('#next').onclick = () => { state.page++; renderResults(); };
  }
  function detail(p) {
    const m = p.model, f = p.plan, same = peers.filter(x => x.category === p.category);
    const sample = (same.length ? same : peers).slice().sort((a,b) => a.mcap_usd/a.tvl_usd - b.mcap_usd/b.tvl_usd);
    const sampleIndices = [...new Set([0, Math.floor((sample.length-1)/2), sample.length-1])];
    main.innerHTML = `<div class="breadcrumb"><a href="#board">All protocols</a><span>/</span><span>${esc(p.category)}</span><span>/</span><span>${esc(p.name)}</span></div>
    <section class="detail-hero"><div><div class="kicker">PROTOCOL DOSSIER / NO TOKEN RECORDED</div><h1>${esc(p.name)}</h1><p>${esc(p.chains.join(' · ') || 'Chain unreported')} &nbsp; / &nbsp; ${p.watchlist ? 'Required watchlist' : 'Extended candidate · parent identity unverified'}</p></div><div class="detail-rank">RANK ${String(p.rank).padStart(2,'0')} / ${rows.length}<br><small>${D.date} snapshot</small></div></section>
    <div class="detail-grid"><section class="card"><div class="card-head"><h2>Implied launch value</h2><span class="pill">CIRCULATING CAP</span></div><div class="big-value">${money(p.implied_value_usd)}</div><div class="range">Sensitivity range ${money(m.low_usd)} – ${money(m.high_usd)} · not a confidence interval</div>
    <div class="formula">${dollars(p.tvl_usd)} × ${ratio(m.multiple)}<br>× ${ratio(m.growth)} growth × ${ratio(m.maturity)} maturity × 0.70<br>= ${dollars(p.implied_value_usd)}</div>
    <div class="factors"><div><span>Snapshot TVL</span><b class="mono">${money(p.tvl_usd)}</b></div><div><span>7-day TVL change</span><b class="mono">${pct(p.change_7d)}</b></div><div><span>Category median</span><b class="mono">${m.category_median === null ? 'N/A' : ratio(m.category_median)}</b></div><div><span>Global median</span><b class="mono">${ratio(m.global_median)}</b></div><div><span>Category weight</span><b class="mono">${(100*m.weight).toFixed(1)}% (${m.peer_count} peers)</b></div><div><span>Tracked since</span><b class="mono">${p.listed_at || 'Unreported'}</b></div></div>
    <p class="caption">Geometric blend toward ${peers.length} global peers; multiple bounded at 0.05–5×. Tracking age ${m.age_days === null ? 'unknown → 0.80× assumed' : m.age_days + ' days (not launch age)'}.${m.missing_growth ? ' Missing growth → neutral 1.00×.' : ''} Transfer discount reflects unobserved token rights and float.</p>
